ear-gradient(135deg,#0284c7 0%,#0369a1 100%);border:none;color:#fff;font-weight:700;font-size:13px;padding:12px;border-radius:10px;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:8px;box-shadow:0 4px 16px rgba(2,132,199,0.4);transition:all 0.2s ease;}.btn-run-sim:hover{transform:translateY(-2px);box-shadow:0 6px 20px rgba(2,132,199,0.5);}.btn-reset-sim{background:transparent;border:1px solid var(--aegis-border-sub);color:var(--aegis-muted);font-size:12px;padding:8px;border-radius:8px;cursor:pointer;}.btn-reset-sim:hover{color:#fff;background:rgba(255,255,255,0.05);}.quick-fix-panel{margin-top:16px;background:rgba(244,63,94,0.1);border:1px solid rgba(244,63,94,0.3);border-radius:10px;padding:14px;animation:fadeIn 0.3s ease;box-sizing:border-box;}.fix-header{font-size:12px;font-weight:700;color:#fb7185;margin-bottom:6px;display:flex;align-items:center;gap:6px;}.fix-desc{font-size:11px;color:#fecdd3;line-height:1.4;margin:0 0 10px;}.btn-quick-pack{width:100%;background:#e11d48;color:#fff;border:none;padding:9px;border-radius:8px;font-size:11px;font-weight:700;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:6px;}.btn-quick-pack:hover{background:#be123c;}.sim-visualizer-card{background:rgba(15,23,42,0.65);border:1px solid var(--aegis-border-sub);border-radius:16px;padding:22px;display:flex;flex-direction:column;width:100%;max-width:100%;min-width:0;box-sizing:border-box;overflow:hidden;}.viz-header{display:flex;justify-content:space-between;align-items:flex-start;gap:14px;margin-bottom:18px;flex-wrap:wrap;}.viz-header > div:first-child{flex:1 1 240px;min-width:0;}.viz-subtitle{font-size:12px;color:var(--aegis-muted);word-break:break-word;}.final-verdict-badge{display:inline-flex;align-items:center;gap:8px;padding:6px 14px;border-radius:10px;background:rgba(10,15,29,0.8);border:1px solid var(--aegis-border-sub);flex-shrink:0;white-space:nowrap;}.verdict-label{font-size:10px;color:var(--aegis-muted);font-weight:700;}.verdict-value{font-size:12px;font-weight:800;}.verdict-standby{color:#94a3b8;}.verdict-pass{color:#34d399;text-shadow:0 0 10px rgba(52,211,153,0.5);}.verdict-fail{color:#fb7185;text-shadow:0 0 10px rgba(251,113,133,0.5);}.steppers-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin-bottom:20px;width:100%;box-sizing:border-box;}@media (max-width:768px){.steppers-grid{grid-template-columns:1fr;}}.step-card{background:rgba(10,15,29,0.6);border:1px solid var(--aegis-border-sub);border-radius:10px;padding:12px 14px;display:flex;align-items:center;gap:10px;transition:all 0.25s ease;min-width:0;width:100%;box-sizing:border-box;}.step-indicator{display:flex;align-items:center;gap:6px;flex-shrink:0;}.step-num{font-size:10px;font-weight:800;color:#64748b;background:rgba(255,255,255,0.05);padding:2px 6px;border-radius:4px;}.step-status-icon{font-size:8px;color:#475569;}.step-content{flex:1;min-width:0;overflow:hidden;}.step-name{font-size:12px;font-weight:700;color:#e2e8f0;margin-bottom:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}.step-detail{font-size:11px;color:#64748b;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;width:100%;}.step-time{font-size:10px;font-family:monospace;color:#64748b;flex-shrink:0;white-space:nowrap;}.step-card.evaluating{border-color:#f59e0b;background:rgba(245,158,11,0.1);box-shadow:0 0 12px rgba(245,158,11,0.2);}.step-card.evaluating .step-status-icon{color:#f59e0b;animation:pulse 0.8s infinite;}.step-card.pass{border-color:rgba(16,185,129,0.5);background:rgba(16,185,129,0.08);}.step-card.pass .step-status-icon{color:#10b981;}.step-card.pass .step-detail{color:#a7f3d0;}.step-card.pass .step-time{color:#34d399;}.step-card.fail{border-color:rgba(244,63,94,0.6);background:rgba(244,63,94,0.12);}.step-card.fail .step-status-icon{color:#f43f5e;}.step-card.fail .step-detail{color:#fecdd3;}.step-card.fail .step-time{color:#fb7185;}.sim-terminal-wrap{background:#030712;border:1px solid var(--aegis-border-sub);border-radius:12px;overflow:hidden;margin-top:auto;width:100%;min-width:0;box-sizing:border-box;}.terminal-bar{display:flex;align-items:center;background:#090d1a;padding:8px 12px;border-bottom:1px solid var(--aegis-border-sub);gap:8px;min-width:0;}.term-dots{display:flex;gap:6px;flex-shrink:0;}.dot{width:9px;height:9px;border-radius:50%;}.dot.red{background:#ef4444;}.dot.yellow{background:#f59e0b;}.dot.green{background:#10b981;}.term-title{margin-left:8px;font-size:11px;font-weight:700;color:#64748b;letter-spacing:0.5px;flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}.btn-copy-term{background:transparent;border:none;color:#94a3b8;font-size:11px;cursor:pointer;flex-shrink:0;white-space:nowrap;}.btn-copy-term:hover{color:#fff;}.terminal-body{padding:14px;margin:0;font-family:'JetBrains Mono','Fira Code',monospace;font-size:11px;color:#38bdf8;line-height:1.6;max-height:240px;overflow-y:auto;overflow-x:auto;white-space:pre-wrap;word-break:break-word;overflow-wrap:anywhere;width:100%;box-sizing:border-box;}.diag-cards-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(320px,1fr));gap:18px;margin-bottom:24px;}.diag-card{background:rgba(15,23,42,0.65);border:1px solid var(--aegis-border-sub);border-radius:14px;overflow:hidden;}.diag-card-head{background:rgba(10,15,29,0.7);padding:12px 16px;font-size:13px;font-weight:700;color:#fff;border-bottom:1px solid var(--aegis-border-sub);display:flex;align-items:center;gap:8px;}.diag-card-body{padding:16px;}.diag-row{display:flex;justify-content:space-between;align-items:center;padding:8px 0;border-bottom:1px solid rgba(255,255,255,0.04);font-size:12px;}.diag-row:last-child{border-bottom:none;}.row-label{color:var(--aegis-muted);}.row-val{font-weight:600;color:#fff;}.badge-success{background:rgba(16,185,129,0.15);color:#34d399;padding:3px 8px;border-radius:6px;font-size:11px;font-weight:700;}.btn-refresh-diag{background:rgba(56,189,248,0.15);color:#38bdf8;border:1px solid rgba(56,189,248,0.3);padding:8px 16px;border-radius:8px;font-size:12px;font-weight:600;cursor:pointer;display:flex;align-items:center;gap:6px;}.btn-refresh-diag:hover{background:rgba(56,189,248,0.25);}.diag-table-card{background:rgba(15,23,42,0.65);border:1px solid var(--aegis-border-sub);border-radius:16px;padding:20px;}.diag-table-header{margin-bottom:16px;}.diag-table-header h3{font-size:15px;font-weight:700;color:#fff;margin:0 0 4px;display:flex;align-items:center;gap:8px;}.table-subtitle{font-size:12px;color:var(--aegis-muted);}.table-responsive{width:100%;overflow-x:auto;-webkit-overflow-scrolling:touch;}.aegis-table{width:100%;border-collapse:collapse;font-size:12px;}.aegis-table th{text-align:left;padding:12px 14px;background:rgba(10,15,29,0.8);color:var(--aegis-muted);font-size:11px;text-transform:uppercase;letter-spacing:0.5px;border-bottom:1px solid var(--aegis-border-sub);}.aegis-table td{padding:12px 14px;border-bottom:1px solid rgba(255,255,255,0.04);color:#cbd5e1;}.aegis-table tr:hover td{background:rgba(255,255,255,0.02);}.mod-name-cell{font-weight:700;color:#fff;}.mod-name-badge{display:flex;align-items:center;gap:8px;}.badge-enc{background:rgba(99,102,241,0.15);color:#818cf8;padding:3px 8px;border-radius:6px;font-size:11px;font-weight:600;}.badge-plain{background:rgba(148,163,184,0.12);color:#94a3b8;padding:3px 8px;border-radius:6px;font-size:11px;}.badge-unlocked{background:rgba(16,185,129,0.15);color:#34d399;padding:3px 8px;border-radius:6px;font-size:11px;font-weight:700;}.badge-tampered{background:rgba(244,63,94,0.15);color:#fb7185;padding:3px 8px;border-radius:6px;font-size:11px;font-weight:700;animation:pulse 1.5s infinite;}.badge-locked{background:rgba(245,158,11,0.15);color:#fbbf24;padding:3px 8px;border-radius:6px;font-size:11px;font-weight:700;}.badge-allowed{background:rgba(56,189,248,0.15);color:#38bdf8;padding:3px 8px;border-radius:6px;font-size:11px;font-weight:700;}.badge-denied{background:rgba(244,63,94,0.15);color:#fb7185;padding:3px 8px;border-radius:6px;font-size:11px;font-weight:700;}.badge-event{background:rgba(168,85,247,0.15);color:#c084fc;padding:3px 8px;border-radius:6px;font-size:11px;font-weight:600;font-family:monospace;}.btn-pack-single{background:rgba(56,189,248,0.12);border:1px solid rgba(56,189,248,0.25);color:#38bdf8;padding:5px 10px;border-radius:6px;font-size:11px;font-weight:600;cursor:pointer;}.btn-pack-single:hover{background:#0284c7;color:#fff;}.workflow-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px;}.wf-step{background:rgba(15,23,42,0.65);border:1px solid var(--aegis-border-sub);border-radius:12px;padding:18px;position:relative;}.wf-num{width:28px;height:28px;background:#0284c7;color:#fff;font-weight:800;font-size:12px;border-radius:50%;display:flex;align-items:center;justify-content:center;margin-bottom:12px;}.wf-step h4{font-size:14px;font-weight:700;color:#fff;margin:0 0 6px;}.wf-step p{font-size:11.5px;color:var(--aegis-muted);line-height:1.5;margin:0 0 10px;}.wf-code{font-size:11px;color:#38bdf8;background:rgba(0,0,0,0.4);padding:5px 8px;border-radius:6px;}.commands-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(360px,1fr));gap:18px;}.cmd-card{background:rgba(15,23,42,0.65);border:1px solid var(--aegis-border-sub);border-radius:14px;padding:20px;}.cmd-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;}.cmd-badge{font-size:10px;font-weight:800;color:#38bdf8;background:rgba(56,189,248,0.12);padding:3px 8px;border-radius:5px;}.btn-copy-cmd{background:transparent;border:none;color:#94a3b8;font-size:13px;cursor:pointer;}.btn-copy-cmd:hover{color:#fff;}.cmd-syntax{font-size:13px;font-weight:700;color:#38bdf8;background:#030712;padding:8px 12px;border-radius:8px;margin-bottom:10px;border:1px solid rgba(255,255,255,0.05);}.cmd-desc{font-size:12px;color:#cbd5e1;line-height:1.5;margin:0 0 10px;}.cmd-note{font-size:11.5px;color:#fde68a;background:rgba(245,158,11,0.1);padding:8px 12px;border-radius:8px;border-left:3px solid #f59e0b;}.text-cyan{color:#06b6d4;}.text-emerald{color:#10b981;}.text-rose{color:#f43f5e;}.text-indigo{color:#818cf8;}.text-muted{color:#94a3b8;}.font-mono{font-family:'JetBrains Mono',monospace;}.mt-6{margin-top:24px;}</style><script>const layerSpecs = { 1: { badge: "SPESIFIKASI LAYER 1", title: "Hardware & Machine Fingerprint Binding", desc: "Mesin proteksi mengekstraksi parameter perangkat keras unik dari sistem operasi (Processor ID, Disk Volume UUID, dan OS Machine GUID) yang dipadukan dengan kunci aplikasi. Token ini mengunci instalasi hanya pada server resmi.", defense: "Jika berkas aplikasi disalin ke server/cloud VPS lain, kalkulasi Installation ID akan menghasilkan nilai berbeda. Lisensi dan seluruh amplop enkripsi seketika menolak diakses (Anti-Kloning).", tips: "Saat migrasi server fisik secara sah, gunakan perintah 'php artisan dapcode:sign-license --install-id=ID_BARU' untuk menghasilkan lisensi baru.", filename: "InstallationService.php", code: ` $fingerprint = hash_hmac('sha256', $cpuId . '|' . $diskSerial . '|' . $machineGuid, config('app.key') ); return 'DAP-' . strtoupper(substr($fingerprint, 0, 6)) . '-' . $uuid;` }, 2: { badge: "SPESIFIKASI LAYER 2", title: "Digital Cryptographic Signature & Asymmetric Authority", desc: "Setiap berkas lisensi ditandatangani secara asimetris menggunakan Kunci Privat Otoritas (RSA-4096 / Ed25519). Mesin runtime hanya menyimpan Kunci Publik Otoritas untuk memvalidasi otentisitas tanda tangan digital.", defense: "Menghalau pemalsuan lisensi. Jika seorang cracker memodifikasi berkas lisensi (misal: memperpanjang expires_at atau menambahkan nama modul), verifikasi tanda tangan OpenSSL akan gagal seketika secara matematis.", tips: "Lisensi bersifat kanonikal. Urutan kunci JSON diurutkan secara alfabetis sebelum dihitung tanda tangannya agar konsisten antar platform.", filename: "LicenseVerifier.php", code: ` $pubKey = openssl_pkey_get_public(File::get($authorityPublicKeyPath)); $canonicalPayload = $this->canonicalJsonEncode($license['payload']); $ok = openssl_verify($canonicalPayload, base64_decode($license['signature']), $pubKey, OPENSSL_ALGO_SHA256); return ($ok === 1);` }, 3: { badge: "SPESIFIKASI LAYER 3", title: "Core Files Self-Integrity Verification (Anti-Crack Seal)", desc: "AegisGuard menyegel berkas-berkas perlindungan inti (LicenseGuard.php, HMVC.php, IntegrityService.php, dll.) dengan daftar hash SHA-256 yang di-seal menggunakan HMAC rahasia instalasi.", defense: "Mencegah serangan Patching/Reverse Engineering. Jika ada cracker yang mengedit kode PHP LicenseGuard untuk mem-bypass lisensi (misal: 'return true;'), segel integritas langsung rusak dan aplikasi memutus seluruh akses.", tips: "Jika Anda memperbarui logika di dalam folder App/Services/Dapcode/, jalankan 'IntegrityService::recordCoreFilesManifest()' untuk merekam segel baru.", filename: "IntegrityService.php", code: ` foreach ($manifest['core_files'] as $relPath => $expectedHash) { $fullPath = base_path($relPath); if (!hash_equals($expectedHash, hash_file('sha256', $fullPath))) { return false; } } return true;` }, 4: { badge: "SPESIFIKASI LAYER 4", title: "Runtime Dynamic Dispatch & Security View Composer", desc: "Mencegat seluruh rute HTTP di lapisan middleware 'dapcode.license' dan dynamic dispatcher HMVC. Selain itu, View Composer didaftarkan untuk setiap namespace view modul ('module::*').", defense: "Mencegah peretasan direct-view atau rute tersembunyi. Tidak ada pengontrol maupun view blade yang dapat dirender ke browser tanpa melewati fungsi LicenseGuard::assertModuleAllowed().", tips: "Setiap modul HMVC yang terdaftar memiliki nama kanonikal yang dinormalisasi untuk mencegah trik bypass melalui manipulasi huruf besar-kecil pada URL.", filename: "HMVC.php", code: ` $canonicalModule = HMVC::resolveCanonicalModuleName($moduleKey); if ($canonicalModule && $canonicalModule !== 'app') { LicenseGuard::assertModuleAllowed($canonicalModule); } View::composer("{$canonicalModule}::*", function($view) use ($canonicalModule) { LicenseGuard::assertModuleAllowed($canonicalModule); });` }, 5: { badge: "SPESIFIKASI LAYER 5", title: "Granular Module Whitelist & Instant Revocation", desc: "Memvalidasi apakah modul yang diminta termasuk di dalam hak akses lisensi. Mendukung mode Wildcard '*' untuk seluruh modul atau daftar array spesifik (misal: ['commerce', 'project']).", defense: "Mendukung saklar darurat 'revoked_modules'. Otoritas pusat dapat mencabut satu modul tertentu secara instan jika ditemukan pelanggaran, tanpa mematikan modul-modul lain.", tips: "Pengecekan waktu kadaluarsa lisensi menggunakan parser ISO-8601 berbasis Carbon dengan batas toleransi clock-skew maksimal 60 detik.", filename: "LicenseGuard.php", code: ` if (in_array(strtolower($module), $license['revoked_modules'] ?? [], true)) { throw new ModuleRevokedException("Module [{$module}] has been revoked."); } return in_array('*', $allowed, true) || in_array(strtolower($module), $allowed, true);` }, 6: { badge: "SPESIFIKASI LAYER 6", title: "Envelope Encryption & Dynamic In-Memory Loader", desc: "Seluruh berkas Controller dan Model dikemas ke dalam amplop enkripsi AES-256-GCM (.php.enc) dengan derivasi kunci PBKDF2 10.000 iterasi dan salt 32-byte unik per-berkas. Dilengkapi Smart Differential Packing agar hanya berkas yang mengalami perubahan yang dienkripsi ulang (Zero Dirty Diffs).", defense: "Plaintext asli dihapus dari disk saat locked (--lock). Saat aplikasi berjalan sah, amplop didekripsi langsung di RAM (in-memory) dan dieksekusi tanpa pernah menuliskan kode kembali ke hard drive fisik.", tips: "Jalankan 'php artisan dapcode:pack [module]' setelah mengedit kode sumber. Berkas yang tidak berubah otomatis diberi status [UNCHANGED] sehingga tidak menimbulkan diff palsu pada Git.", filename: "ModuleEncryptionService.php", code: ` $derivedKey = hash_pbkdf2('sha256', $instId, $salt, 10000, 32, true); $code = openssl_decrypt($ciphertext, 'aes-256-gcm', $derivedKey, OPENSSL_RAW_DATA, $iv, $tag, $relPath); if ($code !== false) { return eval('?>' . $code); }` } }; function switchAegisTab(tabId) { document.querySelectorAll('.aegis-tab-btn').forEach(btn => btn.classList.remove('active')); document.querySelectorAll('.aegis-tab-pane').forEach(pane => pane.classList.remove('active')); event.currentTarget.classList.add('active'); const targetPane = document.getElementById('tab-' + tabId); if (targetPane) targetPane.classList.add('active'); } function showLayerDetail(layerNum) { document.querySelectorAll('.roadmap-card').forEach(card => card.classList.remove('selected')); const targetCard = document.getElementById('layer-card-' + layerNum); if (targetCard) targetCard.classList.add('selected'); const spec = layerSpecs[layerNum]; if (!spec) return; document.getElementById('detail-layer-badge').innerText = spec.badge; document.getElementById('detail-layer-title').innerText = spec.title; document.getElementById('detail-layer-desc').innerText = spec.desc; document.getElementById('detail-layer-defense').innerText = spec.defense; document.getElementById('detail-layer-tips').innerHTML = spec.tips; document.getElementById('detail-code-filename').innerHTML = '<i class="fa-brands fa-php"></i> ' + spec.filename; document.getElementById('detail-code-content').innerText = spec.code; const box = document.getElementById('layer-detail-box'); box.style.display = 'block'; box.scrollIntoView({ behavior: 'smooth', block: 'nearest' }); } function closeLayerDetail() { document.getElementById('layer-detail-box').style.display = 'none'; document.querySelectorAll('.roadmap-card').forEach(card => card.classList.remove('selected')); } const scenarioDescriptions = { happy_path: { title: "Skenario: Request Sah & Lisensi Aktif (Happy Path)", desc: "Menguji alur permintaan normal di mana seluruh 6 layer proteksi memvalidasi identitas mesin, tanda tangan kriptografis, dan integritas amplop tanpa ada anomali." }, aes_decrypt_test: { title: "Skenario: Uji Kriptografis OpenSSL AES-256-GCM In-Memory", desc: "Menguji pembacaan amplop fisik (.php.enc), ekstraksi IV, Authentication Tag, derivasi kunci PBKDF2, dan dekripsi OpenSSL langsung di memori RAM." }, hardware_mismatch: { title: "Skenario: Kloning Server (Installation ID Mismatch)", desc: "Mensimulasikan percobaan kloning berkas aplikasi ke mesin lain yang memiliki Installation ID berbeda. Sistem harus langsung memblokir di Layer 1." }, signature_tampered: { title: "Skenario: Pemalsuan Tanda Tangan Lisensi (Signature Forgery)", desc: "Mensimulasikan peretas yang mengedit atribut lisensi secara ilegal (misal mengubah tanggal kadaluarsa). Verifikasi asimetris RSA-4096 / Ed25519 harus gagal di Layer 2." }, core_tampered: { title: "Skenario: Serangan Modifikasi File Proteksi Inti (Anti-Crack Seal)", desc: "Mensimulasikan modifikasi berkas LicenseGuard.php di disk. Segel HMAC Master Manifest harus mendeteksi ketidakcocokan hash di Layer 3 dan menolak akses." }, module_tampered: { title: "Skenario: Modul Di-minify Tanpa Packing Ulang (TAMPERED)", desc: "Mensimulasikan kasus nyata di mana Controller diubah di disk (misal setelah minifikasi) tetapi belum di-sync ke amplop enkripsi. Layer 6 mendeteksi TAMPERED." }, module_revoked: { title: "Skenario: Pencabutan Modul Tertentu (Granular Revocation)", desc: "Mensimulasikan modul target dimasukkan ke dalam daftar hitam 'revoked_modules'. Akses ke modul diblokir sementara modul lain tetap aktif." }, license_expired: { title: "Skenario: Masa Berlaku Lisensi Habis (License Expired)", desc: "Mensimulasikan tanggal expires_at telah terlewati. Gateway lisensi mendeteksi kadaluarsa dan menampilkan layar aktivasi." } }; function onScenarioChange() { const sc = document.getElementById('sim-scenario').value; const brief = scenarioDescriptions[sc] || scenarioDescriptions.happy_path; document.getElementById('brief-title').innerText = brief.title; document.getElementById('brief-desc').innerText = brief.desc; document.getElementById('quick-fix-panel').style.display = (sc === 'module_tampered') ? 'block' : 'none'; } async function runAegisSimulation() { const scenario = document.getElementById('sim-scenario').value; const module = document.getElementById('sim-module').value; const btn = document.getElementById('btn-run-sim'); const term = document.getElementById('sim-terminal-output'); btn.disabled = true; btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> Menjalankan Simulasi...'; for (let i = 1; i <= 6; i++) { const sc = document.getElementById('step-layer-' + i); sc.className = 'step-card'; document.getElementById('step-detail-' + i).innerText = 'Mempersiapkan pengujian...'; document.getElementById('step-time-' + i).innerText = '-'; } const verdictBadge = document.getElementById('final-verdict-badge'); verdictBadge.innerHTML = '<span class="verdict-label">KEPUTUSAN:</span><span class="verdict-value verdict-standby"><i class="fa-solid fa-spinner fa-spin"></i> EVALUATING</span>'; document.getElementById('viz-status-text').innerText = 'Mengevaluasi alur proteksi Layer 1 s/d Layer 6...'; term.innerText = `[START] Memulai pengujian skenario [${scenario.toUpperCase()}] pada modul [${module}]...\n`; term.innerText += `[TIMESTAMP] ${new Date().toISOString()}\n`; term.innerText += `------------------------------------------------------------\n`; try { const csrfToken = document.querySelector('meta[name="csrf-token"]')?.getAttribute('content') || '{{ csrf_token() }}'; const response = await fetch('/project/aegisguard/simulate', { method: 'POST', headers: { 'Content-Type': 'application/json', 'X-CSRF-TOKEN': csrfToken, 'Accept': 'application/json' }, body: JSON.stringify({ scenario: scenario, module: module }) }); const res = await response.json(); if (res.status === 'success') { for (let idx = 0; idx < res.steps.length; idx++) { const s = res.steps[idx]; const card = document.getElementById('step-layer-' + s.layer); card.className = 'step-card evaluating'; document.getElementById('step-detail-' + s.layer).innerText = 'Mengevaluasi ' + s.name + '...'; await new Promise(r => setTimeout(r, 220)); if (s.status === 'PASS') { card.className = 'step-card pass'; document.getElementById('step-detail-' + s.layer).innerText = s.title; document.getElementById('step-time-' + s.layer).innerText = s.duration_ms + ' ms'; term.innerText += `[PASS] Layer ${s.layer}: ${s.title} (${s.duration_ms} ms)\n`; term.innerText += ` Detail: ${s.message}\n`; } else { card.className = 'step-card fail'; document.getElementById('step-detail-' + s.layer).innerText = s.title; document.getElementById('step-time-' + s.layer).innerText = s.duration_ms + ' ms'; term.innerText += `[FAIL] Layer ${s.layer}: ${s.title} (${s.duration_ms} ms)\n`; term.innerText += ` Audit Event: ${s.audit_event} | Reason: ${s.message}\n`; break; } } await new Promise(r => setTimeout(r, 150)); term.innerText += `------------------------------------------------------------\n`; if (res.verdict === 'GRANTED') { verdictBadge.innerHTML = '<span class="verdict-label">KEPUTUSAN:</span><span class="verdict-value verdict-pass"><i class="fa-solid fa-circle-check"></i> GRANTED (HTTP 200)</span>'; document.getElementById('viz-status-text').innerText = 'Seluruh 6 Layer Lolos! Akses modul diberikan.'; term.innerText += `[VERDICT] ACCESS GRANTED. Seluruh lapisan aman (${res.total_elapsed_ms} ms total).\n`; } else { verdictBadge.innerHTML = `<span class="verdict-label">KEPUTUSAN:</span><span class="verdict-value verdict-fail"><i class="fa-solid fa-ban"></i> BLOCKED (${res.http_code})</span>`; document.getElementById('viz-status-text').innerText = `Akses Ditolak di ${res.failure_reason}. HTTP ${res.http_code} Forbidden.`; term.innerText += `[VERDICT] ACCESS BLOCKED (${res.http_code} FORBIDDEN).\n`; term.innerText += `[CAUSE] ${res.failure_reason}\n`; if (scenario === 'module_tampered') { document.getElementById('quick-fix-panel').style.display = 'block'; } } } else { term.innerText += `[ERROR] Gagal menjalankan simulasi: ${res.message}\n`; } } catch (err) { term.innerText += `[FATAL] Error komunikasi dengan server: ${err.message}\n`; } finally { btn.disabled = false; btn.innerHTML = '<i class="fa-solid fa-play"></i> Jalankan Simulasi Kriptografis'; term.scrollTop = term.scrollHeight; } } function resetAegisSimulation() { for (let i = 1; i <= 6; i++) { const sc = document.getElementById('step-layer-' + i); sc.className = 'step-card'; document.getElementById('step-detail-' + i).innerText = 'Menunggu evaluasi...'; document.getElementById('step-time-' + i).innerText = '-'; } const verdictBadge = document.getElementById('final-verdict-badge'); verdictBadge.innerHTML = '<span class="verdict-label">KEPUTUSAN:</span><span class="verdict-value verdict-standby">STANDBY</span>'; document.getElementById('viz-status-text').innerText = 'Menunggu instruksi simulasi...'; document.getElementById('sim-terminal-output').innerText = '[RESET] Simulator dikembalikan ke kondisi standby.\n'; document.getElementById('quick-fix-panel').style.display = 'none'; } async function triggerQuickPack() { const mod = document.getElementById('sim-module').value; const term = document.getElementById('sim-terminal-output'); term.innerText += `\n[ACTION] Menjalankan perintah artisan 'php artisan dapcode:pack ${mod}'...\n`; try { const csrfToken = document.querySelector('meta[name="csrf-token"]')?.getAttribute('content') || '{{ csrf_token() }}'; const res = await fetch('/project/aegisguard/pack', { method: 'POST', headers: { 'Content-Type': 'application/json', 'X-CSRF-TOKEN': csrfToken, 'Accept': 'application/json' }, body: JSON.stringify({ module: mod }) }); const data = await res.json(); if (data.status === 'success') { term.innerText += `[SUCCESS] ${data.message}\n`; term.innerText += data.output + '\n'; term.innerText += `[RE-TEST] Menjalankan ulang simulasi normal...\n`; document.getElementById('sim-scenario').value = 'happy_path'; onScenarioChange(); runAegisSimulation(); } else { term.innerText += `[ERROR] ${data.message}\n`; } } catch (e) { term.innerText += `[ERROR] Gagal memanggil fungsi pack: ${e.message}\n`; } term.scrollTop = term.scrollHeight; } function showAegisToast(message, type = 'info', title = '') { if (window.DapToast && typeof window.DapToast[type] === 'function') { window.DapToast[type](message, title || (type === 'success' ? 'Berhasil' : (type === 'error' ? 'Terjadi Kesalahan' : (type === 'warning' ? 'Peringatan' : 'Informasi')))); return; } if (window.DapUI && window.DapUI.toast && typeof window.DapUI.toast[type] === 'function') { window.DapUI.toast[type](message, title || (type === 'success' ? 'Berhasil' : (type === 'error' ? 'Terjadi Kesalahan' : (type === 'warning' ? 'Peringatan' : 'Informasi')))); return; } let container = document.getElementById('ui-toast-container'); if (!container) { container = document.createElement('div'); container.id = 'ui-toast-container'; container.className = 'ui-toast-container'; document.body.appendChild(container); } const icons = { success: 'fa-solid fa-circle-check', error: 'fa-solid fa-circle-exclamation', warning: 'fa-solid fa-triangle-exclamation', info: 'fa-solid fa-circle-info' }; const toast = document.createElement('div'); toast.className = `ui-toast ui-toast-${type}`; const defaultTitle = title || (type === 'success' ? 'Berhasil' : (type === 'error' ? 'Terjadi Kesalahan' : (type === 'warning' ? 'Peringatan' : 'Informasi'))); toast.innerHTML = ` <div class="ui-toast-icon"><i class="${icons[type] || icons.info}"></i></div><div class="ui-toast-body"><div class="ui-toast-title">${defaultTitle}</div><div class="ui-toast-message">${message}</div></div><button type="button" class="ui-toast-close" onclick="this.closest('.ui-toast').remove()"><i class="fa-solid fa-xmark"></i></button> `; container.appendChild(toast); setTimeout(() => { toast.classList.add('is-closing'); setTimeout(() => toast.remove(), 250); }, 4000); } function showAegisConfirm(message, title = 'Konfirmasi Tindakan', type = 'warning') { if (window.DapConfirm) { return window.DapConfirm({ title, message, type, confirmText: 'Lanjutkan', cancelText: 'Batal' }); } if (window.DapUI && window.DapUI.confirm) { return window.DapUI.confirm({ title, message, type, confirmText: 'Lanjutkan', cancelText: 'Batal' }); } return new Promise((resolve) => { let dialog = document.getElementById('ui-confirm-dialog-singleton'); if (dialog) dialog.remove(); dialog = document.createElement('div'); dialog.id = 'ui-confirm-dialog-singleton'; dialog.className = 'ui-modal-backdrop is-open'; dialog.style.zIndex = '10005'; dialog.innerHTML = ` <div class="ui-modal ui-modal-sm"><div class="ui-modal-body" style="text-align: center; padding: 28px 24px 20px;"><div style="width: 56px; height: 56px; border-radius: 50%; margin: 0 auto 16px; display: flex; align-items: center; justify-content: center; font-size: 24px; background: rgba(245, 158, 11, 0.15); color: #f59e0b;"><i class="fa-solid fa-triangle-exclamation"></i></div><h3 style="font-size: 17px; font-weight: 700; color: #fff; margin-bottom: 8px;">${title}</h3><p style="font-size: 13.5px; color: #94a3b8; line-height: 1.5; margin: 0;">${message}</p></div><div class="ui-modal-footer" style="justify-content: center; gap: 12px; border-top: none; padding: 0 24px 24px; background: transparent; display: flex;"><button type="button" class="ui-btn ui-btn-secondary" id="aegis-cancel-btn" style="padding: 9px 20px; border-radius: 8px; cursor: pointer;"><i class="fa-solid fa-xmark"></i> Batal </button><button type="button" class="ui-btn ui-btn-primary" id="aegis-ok-btn" style="padding: 9px 20px; border-radius: 8px; cursor: pointer;"><i class="fa-solid fa-check"></i> Lanjutkan </button></div></div> `; document.body.appendChild(dialog); const close = (val) => { dialog.remove(); resolve(val); }; dialog.querySelector('#aegis-cancel-btn').onclick = () => close(false); dialog.querySelector('#aegis-ok-btn').onclick = () => close(true); }); } window.alert = function(msg) { showAegisToast(msg, 'info'); }; async function packSingleModule(modKey) { const ok = await showAegisConfirm(`Apakah Anda yakin ingin mengemas ulang amplop enkripsi untuk modul [${modKey}]?`, 'Kemas Ulang Modul', 'warning'); if (!ok) return; try { const csrfToken = document.querySelector('meta[name="csrf-token"]')?.getAttribute('content') || '{{ csrf_token() }}'; const res = await fetch('/project/aegisguard/pack', { method: 'POST', headers: { 'Content-Type': 'application/json', 'X-CSRF-TOKEN': csrfToken, 'Accept': 'application/json' }, body: JSON.stringify({ module: modKey }) }); const data = await res.json(); if (data.status === 'success') { showAegisToast(data.message || `Amplop enkripsi modul [${modKey}] berhasil dikemas ulang!`, 'success'); } else { showAegisToast(data.message || 'Gagal mengemas modul', 'error'); } refreshDiagnostics(); } catch(e) { showAegisToast('Gagal: ' + e.message, 'error'); } } async function refreshDiagnostics() { try { const res = await fetch('/project/aegisguard/diagnostics'); const data = await res.json(); if (data.status === 'success') { const d = data.data; document.getElementById('diag-inst-id').innerText = d.installation_id; const tbody = document.getElementById('modules-table-body'); tbody.innerHTML = ''; d.modules.forEach(m => { const tr = document.createElement('tr'); tr.innerHTML = ` <td class="mod-name-cell"><div class="mod-name-badge"><i class="fa-solid fa-cube"></i> ${m.name}</div></td><td>${m.encrypted ? '<span class="badge-enc"><i class="fa-solid fa-lock"></i> Encrypted (.php.enc)</span>' : '<span class="badge-plain">Plaintext</span>'}</td><td><span class="${m.status === 'UNLOCKED' ? 'badge-unlocked' : (m.status === 'TAMPERED' ? 'badge-tampered' : 'badge-locked')}"><i class="fa-solid ${m.status === 'UNLOCKED' ? 'fa-circle-check' : 'fa-lock'}"></i> ${m.status}</span></td><td><span class="${m.allowed ? 'badge-allowed' : 'badge-denied'}"><i class="fa-solid ${m.allowed ? 'fa-check' : 'fa-xmark'}"></i> ${m.allowed ? 'ALLOWED' : 'DENIED'}</span></td><td><button class="btn-pack-single" onclick="packSingleModule('${m.key}')"><i class="fa-solid fa-box-archive"></i> Pack Ulang</button></td> `; tbody.appendChild(tr); }); showAegisToast('Diagnostik berhasil disegarkan!', 'success'); } else { showAegisToast('Gagal memuat diagnostik: ' + (data.message || 'Terjadi kesalahan'), 'error'); } } catch (e) { showAegisToast('Gagal menyegarkan diagnostik: ' + e.message, 'error'); } } function copyTerminalLogs() { const text = document.getElementById('sim-terminal-output').innerText; navigator.clipboard.writeText(text).then(() => { showAegisToast('Log simulasi berhasil disalin ke clipboard!', 'info'); }).catch(() => { showAegisToast('Log simulasi berhasil disalin ke clipboard!', 'info'); }); } function copyText(str) { navigator.clipboard.writeText(str).then(() => { showAegisToast('Perintah berhasil disalin: ' + str, 'info'); }).catch(() => { showAegisToast('Perintah berhasil disalin: ' + str, 'info'); }); }</script>